// Normalise the Stripe invoice payload into a flat row
// the Google Sheets node can append directly.
// Amounts come from Stripe in the smallest currency unit
// (paise / cents) — we keep that convention and ALSO emit a
// human-readable major-unit value so the sheet is browseable.

const invoice = $input.first().json.data?.object ?? $input.first().json;
const minor = (n) => (typeof n === 'number' ? n : 0);
const major = (n) => (minor(n) / 100).toFixed(2);

const customer = invoice.customer_email
  || invoice.customer_address?.email
  || invoice.customer
  || '';

const hostedUrl = invoice.hosted_invoice_url || invoice.invoice_pdf || '';
const createdIso = invoice.created
  ? new Date(invoice.created * 1000).toISOString()
  : new Date().toISOString();
const paidIso = invoice.status_transitions?.paid_at
  ? new Date(invoice.status_transitions.paid_at * 1000).toISOString()
  : createdIso;

return [
  {
    json: {
      stripe_invoice_id: invoice.id || '',
      number: invoice.number || '',
      customer_email: customer,
      currency: (invoice.currency || 'usd').toUpperCase(),
      amount_due_minor: minor(invoice.amount_due),
      amount_paid_minor: minor(invoice.amount_paid),
      tax_minor: minor(invoice.tax),
      total_minor: minor(invoice.total),
      amount_paid_major: major(invoice.amount_paid),
      tax_major: major(invoice.tax),
      total_major: major(invoice.total),
      status: invoice.status || '',
      created_at: createdIso,
      paid_at: paidIso,
      hosted_invoice_url: hostedUrl,
      first_line_description:
        invoice.lines?.data?.[0]?.description || '',
    },
  },
];
